import io

# BufferedWriter needs to call write() and use its return value.
# It sends data as memoryview, and expects the write to return the count.
# Let's check what spooled bytesio needs

class TestWriter(io.BufferedIOBase):
    def __init__(self, inner):
        self._inner = inner

    def write(self, data):
        print(f'TestWriter.write got type: {type(data).__name__}')
        result = self._inner.write(data)
        print(f'Inner write returned: {result}')
        if result is None:
            print('BUG: should return byte count!')
        return result

    def writable(self):
        return True

    def flush(self):
        return self._inner.flush()

    def seekable(self):
        return True

    def seek(self, pos, mode=0):
        return self._inner.seek(pos, mode)

    def close(self):
        return self._inner.close()

from boltons import ioutils
s = ioutils.SpooledBytesIO()
bw = TestWriter(s)
ret = bw.write(b'test')
print(f'Got back: {ret}')
