def seek(self, pos, mode=0):
    """Traverse from offset to the specified codepoint"""
    self._checkClosed()
    if mode == os.SEEK_SET:
        start_pos = self.tell()
        buffer_pos = self.buffer.tell()
        if pos < 0:
            raise ValueError("negative seek position {} is not valid".format(pos))
        self.buffer.seek(0)
        self._traverse_codepoints(0, pos)
        self._tell = pos
    elif mode == os.SEEK_CUR:
        current_pos = self.tell()
        buffer_pos = self.buffer.tell()
        new_pos = current_pos + pos
        if new_pos < 0:
            raise ValueError("negative seek position {} is not valid".format(new_pos))
        if pos >= 0:
            self._traverse_codepoints(current_pos, pos)
            self._tell = new_pos
        else:
            # Backward seek: save position, seek to start, traverse to target
            self.buffer.seek(0)
            self._traverse_codepoints(0, new_pos)
            self._tell = new_pos
    elif mode == os.SEEK_END:
        start_pos = self.tell()
        buffer_pos = self.buffer.tell()
        dest_position = self.len - pos
        if dest_position < 0:
            raise ValueError("negative seek position {} is not valid".format(dest_position))
        self.buffer.seek(0)
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    else:
        raise ValueError(
            f"Invalid whence ({mode}, should be 0, 1, or 2)"
        )
    return self.tell()

